package com.bank.search.repository;

import com.bank.search.dto.AccountOverview;
import com.bank.search.model.Account;
import com.bank.search.projection.AccountSummary;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.util.List;

public interface AccountRepository extends JpaRepository<Account, String> {

    // Interface projection (3 columns + SpEL computed):
    List<AccountSummary> findByStatus(String status);
    // SQL: SELECT account_id, holder_name, balance FROM accounts WHERE status = ?

    // DTO projection with constructor expression:
    @Query("SELECT new com.bank.search.dto.AccountOverview(a.accountId, a.holderName, a.balance) " +
           "FROM Account a WHERE a.holderName LIKE %:name%")
    List<AccountOverview> searchByName(@Param("name") String name);
    // SQL: SELECT account_id, holder_name, balance FROM accounts WHERE holder_name LIKE ?

    // Dynamic projection — caller picks:
    <T> List<T> findByAccountType(String accountType, Class<T> type);
}
