// ─── File: src/main/java/com/bank/search/service/CustomerSearchService.java ───
package com.bank.search.service;

import com.bank.search.dto.AccountOverview;
import com.bank.search.model.Account;
import com.bank.search.projection.AccountSummary;
import com.bank.search.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class CustomerSearchService {

    private final AccountRepository accountRepo;

    @Transactional(readOnly = true)
    public List<AccountSummary> searchWithInterface() {
        List<AccountSummary> results = accountRepo.findByStatus("ACTIVE");
        log.info("[INTERFACE] {} results, SpEL displayName: {}",
            results.size(), results.isEmpty() ? "N/A" : results.get(0).getDisplayName());
        return results;
    }

    @Transactional(readOnly = true)
    public List<AccountOverview> searchWithDto(String name) {
        List<AccountOverview> results = accountRepo.searchByName(name);
        log.info("[DTO] {} results for name containing '{}'", results.size(), name);
        return results;
    }

    @Transactional(readOnly = true)
    public <T> List<T> searchDynamic(String accountType, Class<T> type) {
        List<T> results = accountRepo.findByAccountType(accountType, type);
        log.info("[DYNAMIC] {} results as {}", results.size(), type.getSimpleName());
        return results;
    }
}
```

