package com.bank.search.controller;

import com.bank.search.dto.AccountOverview;
import com.bank.search.projection.AccountSummary;
import com.bank.search.service.CustomerSearchService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.util.List;

@RestController
@RequestMapping("/api/v1/search")
@RequiredArgsConstructor
public class SearchController {

    private final CustomerSearchService service;

    @GetMapping("/interface")
    public List<AccountSummary> interfaceProjection() { return service.searchWithInterface(); }

    @GetMapping("/dto")
    public List<AccountOverview> dtoProjection(@RequestParam String name) {
        return service.searchWithDto(name);
    }

    @GetMapping("/dynamic/{type}")
    public List<AccountOverview> dynamic(@PathVariable String type) {
        return service.searchDynamic(type, AccountOverview.class);
    }
}
