package com.bank.search.service;

import com.bank.search.dto.AccountOverview;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class ProjectionDeepDiveTest {

    @Test
    void dtoRecordFetchesOnlyNeededColumns() {
        AccountOverview dto = new AccountOverview("SAV2001", "Rajesh Kumar", new BigDecimal("125000"));
        assertThat(dto.accountId()).isEqualTo("SAV2001");
        // dto has NO: phone, email, pan, aadhaar, address, auditHistory
        // → 85% less data than full Account entity with 15 columns
    }

    @Test
    void dataSavingsCalculation() {
        int fullEntityColumns = 15;
        int projectionColumns = 3;
        double savings = 1.0 - ((double) projectionColumns / fullEntityColumns);
        assertThat(savings).isEqualTo(0.8);  // 80% fewer columns

        // Plus: no persistence context (snapshot + dirty checking) → additional 50% memory savings
    }
}
